function load(){try{const x=JSON.parse(localStorage.getItem("undici-auction")||"{}"),called={...(x.called||{})};(x.passed||[]).forEach(k=>called[k]??={price:null,outcome:"other"});const participantCount=clampParticipants(x.participantCount||((x.opponents?.length||9)+1));return{...defaults,...x,participantCount,opponents:normalizeOpponents(participantCount,x.opponents),called,slots:{...defaults.slots,...(x.slots||{})},roleBudgets:{...defaults.roleBudgets,...(x.roleBudgets||{})},liveRoleBudgets:x.liveRoleBudgets?{...defaults.roleBudgets,...x.liveRoleBudgets}:null}}catch{return structuredClone(defaults)}}
function save(){localStorage.setItem("undici-auction",JSON.stringify(state));const label=$("#saveStatus");if(label){const time=new Date().toLocaleTimeString("it-IT",{hour:"2-digit",minute:"2-digit"});label.textContent=`Salvato automaticamente alle ${time}`}}
const key=p=>`${p.name}|${p.club}`;
function starterTierSignature(){let hash=2166136261;players.forEach(p=>{const text=`${key(p)}|${p.role}|${p.fvm}|${p.quotation};`;for(let i=0;i<text.length;i++){hash^=text.charCodeAt(i);hash=Math.imul(hash,16777619)}});return `list-${players.length}-${(hash>>>0).toString(16)}`}
function starterTiers(){const cuts=[.10,.30,.60,.85,1],labels=["S","A","B","C","D"],result=[];Object.keys(state.slots).forEach(role=>{const count=Math.min(players.filter(p=>p.role===role).length,state.participantCount*state.slots[role]),list=players.filter(p=>p.role===role).sort((a,b)=>Number(b.fvm)-Number(a.fvm)||Number(b.quotation)-Number(a.quotation)||a.name.localeCompare(b.name,"it")).slice(0,count);list.forEach((player,index)=>{const ratio=(index+1)/Math.max(1,count),tier=labels[cuts.findIndex(cut=>ratio<=cut)];result.push({key:key(player),tier,cost:Math.max(1,Math.round(Number(player.fvm||1)*state.budget/1000))})})});return result}
function tierSetupMarkup(){return '<section class="tier-starter-notice panel" id="tierStarterNotice"><div><span id="tierStarterEyebrow">FASCE IN EVOLUZIONE</span><h2 id="tierStarterTitle">Una base da personalizzare</h2><p id="tierStarterText"></p><small id="tierStarterCoverage"></small></div><div class="tier-starter-actions"><button id="tierStarterUpdate" type="button" hidden>Aggiungi i nuovi suggeriti</button><button id="tierStarterReset" type="button">Ripristina base neutrale</button></div></section>'}
function tierWelcomeMarkup(){return '<dialog id="tierWelcome" class="tier-welcome"><div class="tier-welcome-sheet"><span>PRIMO ACCESSO</span><h2>Come vuoi iniziare con le Fasce?</h2><p>Le Fasce neutre sono soltanto una base incompleta generata dal listone. Controlla prezzi, ordine e priorità in base alla tua strategia.</p><div><button id="useStarterTiers" class="primary" type="button"><b>Usa la base neutrale</b><small>Inizia subito e poi personalizzala</small></button><button id="welcomeImportTiers" type="button"><b>Importa le mie Fasce</b><small>Usa un file esportato da FANTAMURETTO</small></button><button id="startEmptyTiers" type="button"><b>Parti da zero</b><small>Nessun giocatore già classificato</small></button></div><footer>La base viene aggiornata insieme al listone, ma le tue modifiche non saranno mai sovrascritte automaticamente.</footer></div></dialog>'}
function renderTierStarterNotice(){const box=$("#tierStarterNotice");if(!box||!players.length)return;if(!state.tierSetupDone&&(state.targets||[]).length){state.tierSetupDone=true;state.tierSource="personal";state.tierPresetSignature=starterTierSignature();if($("#tierWelcome")?.open)$("#tierWelcome").close()}const classified=new Set((state.targets||[]).filter(x=>players.some(p=>key(p)===x.key)).map(x=>x.key)).size,missing=players.length-classified,signature=starterTierSignature(),updateAvailable=!!state.tierPresetSignature&&state.tierPresetSignature!==signature,suggestedMissing=starterTiers().filter(x=>!(state.targets||[]).some(t=>t.key===x.key)).length;box.classList.toggle("update-available",updateAvailable);$("#tierStarterEyebrow").textContent=updateAvailable?"AGGIORNAMENTO DISPONIBILE":"FASCE IN EVOLUZIONE";$("#tierStarterTitle").textContent=state.tierSource==="starter"?"Fasce iniziali da personalizzare":"Le tue Fasce non sono definitive";$("#tierStarterText").textContent=updateAvailable?"Il listone pubblicato è cambiato. Puoi aggiungere i nuovi suggerimenti senza modificare prezzi, fasce e ordine che hai già scelto.":"Non sono Fasce complete: modificale secondo la tua strategia e resta aggiornato, perché nuovi acquisti e trasferimenti possono cambiare il listone.";$("#tierStarterCoverage").textContent=`${classified} giocatori classificati su ${players.length} · ${missing} ancora da valutare`;$("#tierStarterUpdate").hidden=!updateAvailable;$("#tierStarterUpdate").textContent=suggestedMissing?`Aggiungi nuovi suggeriti (${suggestedMissing})`:"Segna aggiornamento come visto"}
function applyStarterTiers(replace=false){const suggestions=starterTiers(),known=new Set((state.targets||[]).map(x=>x.key)),added=replace?suggestions:suggestions.filter(x=>!known.has(x.key));if(replace)state.targets=suggestions;else state.targets.push(...added);state.tierSetupDone=true;state.tierSource=replace?"starter":state.tierSource||"personal";state.tierPresetSignature=starterTierSignature();renderAll();return added.length}
function bindTierStarter(){$("#useStarterTiers").onclick=()=>{$("#tierWelcome").close();const count=applyStarterTiers(true);toast(`${count} suggerimenti iniziali aggiunti`)};$("#welcomeImportTiers").onclick=()=>$("#backupFile").click();$("#startEmptyTiers").onclick=()=>{state.tierSetupDone=true;state.tierSource="empty";state.tierPresetSignature=starterTierSignature();$("#tierWelcome").close();renderAll();toast("Fasce vuote pronte da compilare")};$("#tierStarterReset").onclick=()=>{if(!confirm("Sostituire le Fasce attuali con la base neutrale? Prezzi, ordine e classificazioni personali verranno rimossi."))return;const count=applyStarterTiers(true);toast(`Base neutrale ripristinata · ${count} giocatori`)};$("#tierStarterUpdate").onclick=()=>{const count=applyStarterTiers(false);toast(count?`${count} nuovi suggerimenti aggiunti senza modificare le tue Fasce`:"Aggiornamento del listone registrato")}}
function ensureTierSetupUi(){if($("#tierStarterNotice"))return;$(".tier-toolbar").insertAdjacentHTML("beforebegin",tierSetupMarkup());document.body.insertAdjacentHTML("beforeend",tierWelcomeMarkup());bindTierStarter();queueMicrotask(()=>{renderTierStarterNotice();if(!state.tierSetupDone&&!$("#tierWelcome").open)$("#tierWelcome").showModal()})}
const status=p=>state.bought[key(p)]?"mine":state.called[key(p)]?"passed":"available";
const esc=v=>String(v).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const boughtPlayers=()=>players.filter(p=>state.bought[key(p)]).map(p=>({...p,price:state.bought[key(p)]}));
const pct=value=>`${(Number(value||0)/Math.max(1,state.budget)*100).toLocaleString("it-IT",{minimumFractionDigits:0,maximumFractionDigits:1})}%`;
function stats(){const bought=boughtPlayers(),spent=bought.reduce((n,p)=>n+Number(p.price),0),counts=Object.fromEntries(Object.keys(state.slots).map(r=>[r,bought.filter(p=>p.role===r).length])),slotsLeft=Object.keys(state.slots).reduce((n,r)=>n+Math.max(0,state.slots[r]-counts[r]),0),budgetLeft=state.budget-spent;return{bought,spent,counts,slotsLeft,budgetLeft,maxBid:Math.max(0,budgetLeft-Math.max(0,slotsLeft-1))}}
const ownerName=id=>state.opponents?.find(x=>x.id===id)?.name||"Squadra non specificata";
function refreshOwnerSelects(){const options='<option value="">Non specificata — assegna dopo</option>'+state.opponents.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join("");[$("#otherOwner"),$("#quickOtherOwner")].forEach(select=>{if(!select)return;const previous=select.value;select.innerHTML=options;if([...select.options].some(x=>x.value===previous))select.value=previous})}
function opponentStats(opponentId){const purchases=Object.entries(state.called||{}).filter(([,call])=>call?.outcome==="other"&&call.ownerId===opponentId).map(([playerKey,call])=>({player:players.find(p=>key(p)===playerKey),price:Number(call.price||0)})).filter(x=>x.player),spent=purchases.reduce((sum,x)=>sum+x.price,0),counts=Object.fromEntries(Object.keys(state.slots).map(r=>[r,purchases.filter(x=>x.player.role===r).length])),slotsLeft=Object.keys(state.slots).reduce((sum,r)=>sum+Math.max(0,state.slots[r]-counts[r]),0),budgetLeft=Math.max(0,state.budget-spent);return{purchases,spent,counts,slotsLeft,budgetLeft,maxBid:Math.max(0,budgetLeft-Math.max(0,slotsLeft-1))}}
